package com.familya.sharing.adapter.out.persistence;
import com.familya.sharing.application.port.out.ShareLinkRepository; import com.familya.sharing.domain.model.ShareLink; import org.springframework.jdbc.core.namedparam.*; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.*; import java.sql.Timestamp; import java.util.*;
@Component public class JdbcShareLinkRepository implements ShareLinkRepository {private final NamedParameterJdbcTemplate jdbc;public JdbcShareLinkRepository(NamedParameterJdbcTemplate j){jdbc=j;}@Transactional(propagation=Propagation.MANDATORY)public void insert(ShareLink l){jdbc.update("INSERT INTO share_link (id,tree_id,scope,target_id,role,token_hash,created_by_user_id,created_at,expires_at,revoked_at,revocation_reason,revision,version) VALUES (:id,:tree,:scope,:target,:role,:hash,:creator,:created,:expires,:revoked,:reason,:revision,:version)",params(l));}@Transactional(propagation=Propagation.MANDATORY)public void update(ShareLink l){jdbc.update("UPDATE share_link SET revoked_at=:revoked,revocation_reason=:reason,revision=:revision,version=:version WHERE id=:id",params(l));}public Optional<ShareLink> findById(UUID id){return one("SELECT * FROM share_link WHERE id=:x",id.toString());}public Optional<ShareLink> findByTokenHash(String hash){return one("SELECT * FROM share_link WHERE token_hash=:x",hash);}public List<ShareLink> listByTree(UUID id){return jdbc.queryForList("SELECT * FROM share_link WHERE tree_id=:x ORDER BY created_at DESC",Map.of("x",id.toString())).stream().map(this::row).toList();}private Optional<ShareLink> one(String sql,String x){var r=jdbc.queryForList(sql,Map.of("x",x));return r.isEmpty()?Optional.empty():Optional.of(row(r.get(0)));}private MapSqlParameterSource params(ShareLink l){return new MapSqlParameterSource().addValue("id",l.id().toString()).addValue("tree",l.treeId().toString()).addValue("scope",l.scope().name()).addValue("target",l.targetId()==null?null:l.targetId().toString()).addValue("role",l.role().name()).addValue("hash",l.tokenHash()).addValue("creator",l.createdByUserId().toString()).addValue("created",Timestamp.from(l.createdAt())).addValue("expires",l.expiresAt()==null?null:Timestamp.from(l.expiresAt())).addValue("revoked",l.revokedAt()==null?null:Timestamp.from(l.revokedAt())).addValue("reason",l.revocationReason()).addValue("revision",l.revision()).addValue("version",l.version());}private ShareLink row(Map<String,Object> r){return new ShareLink(UUID.fromString((String)r.get("id")),UUID.fromString((String)r.get("tree_id")),ShareLink.Scope.valueOf((String)r.get("scope")),r.get("target_id")==null?null:UUID.fromString((String)r.get("target_id")),ShareLink.Role.valueOf((String)r.get("role")),(String)r.get("token_hash"),UUID.fromString((String)r.get("created_by_user_id")),((Timestamp)r.get("created_at")).toInstant(),r.get("expires_at")==null?null:((Timestamp)r.get("expires_at")).toInstant(),r.get("revoked_at")==null?null:((Timestamp)r.get("revoked_at")).toInstant(),(String)r.get("revocation_reason"),((Number)r.get("revision")).longValue(),((Number)r.get("version")).longValue());}}
